import json
from pathlib import Path
qs=[]
def single(r,p,o,e):add(r,'single',p,o,[0],e)
def multi(r,p,o,a,e):add(r,'multi',p,o,a,e)
def order(r,p,o,e):add(r,'order',p,o,list(range(len(o))),e)
def pairs(r,p,o,e):add(r,'match',p,o,[],e)
def add(r,t,p,o,a,e):qs.append(dict(id='concept-'+str(len(qs)+1).zfill(3),type=t,category=int(r.split('.')[0]),sourceIds=['y26-'+r],track='concept',prompt=p,options=o,answer=a,explanation=e))
single('1.1','How are IoC and dependency injection related?',['IoC is a design principle; DI is one way to implement it.','DI is a principle; IoC means field injection only.','IoC requires business code to instantiate every dependency.','DI primarily increases coupling between implementations.'],'IoC delegates object creation and assembly to a container. DI supplies dependencies from outside, improving decoupling and testability.')
pairs('1.2','Match each bean declaration mechanism to its typical role.',[['@Component','Register an application class through scanning'],['@Bean','Register an object returned by a factory method'],['@Configuration','Declare a bean configuration class']],'Use @Bean when constructing third-party objects or when explicit configuration is needed.')
multi('1.3','Which conveniences does Spring Boot provide?',['Auto-configuration','Starter dependencies','Embedded web servers','A guarantee that no application configuration is needed'],[0,1,2],'Spring Boot builds on Spring with conventions and automatic setup. Application-specific configuration is still necessary.')
single('1.4','What does ApplicationContext add to the basic BeanFactory abstraction?',['Application events, internationalization, and broader framework integration','It removes bean lifecycle management','It prevents access to beans','It only works inside web applications'],'ApplicationContext extends BeanFactory with richer application facilities. Lazy versus eager behavior is configurable, not an absolute distinction.')
multi('1.5','Why prefer constructor injection for required dependencies?',['Required dependencies are explicit','Dependencies can be stored in final fields','Tests can construct objects directly','It automatically resolves every circular dependency'],[0,1,2],'Constructor injection makes dependencies visible and testable. Constructor cycles usually require design changes.')
single('1.6','A singleton receives a prototype bean through constructor injection. Does every method call get a new prototype?',['No. Use on-demand lookup such as ObjectProvider for repeated retrieval.','Yes. Every method invocation creates a new instance.','Yes. Every field read creates a new instance.','No. These scopes cannot depend on each other.'],'Normal injection happens once when the singleton is built. Scope does not change ordinary field access semantics.')
order('1.7','Order the main lifecycle stages of a managed singleton bean. Aware callbacks and post-processors are omitted.',['Instantiate the bean','Inject its dependencies','Run initialization callbacks','Use the bean','Run destruction callbacks when the container closes'],'The full lifecycle also includes Aware callbacks and BeanPostProcessors. Prototype destruction is normally not managed by the container.')
order('1.9','Order the stages of this conventional layered REST request.',['Controller receives and validates the request','Service executes business logic','Repository accesses the database','Map the result to a response DTO'],'Layering separates HTTP concerns, business rules, and persistence. This describes one conventional flow, not every possible implementation.')
single('1.10','Two services require each other through their constructors. What is the preferred first response?',['Refactor responsibilities or extract a third collaborator','Add @Primary to both classes','Make every field static','Disable the unit tests'],'Circular dependencies often indicate unclear boundaries. @Lazy or ObjectProvider can defer resolution but do not replace a design fix.')
pairs('1.11','Match each injection annotation to its role.',[['@Qualifier','Select a specific candidate bean'],['@Primary','Prefer one bean among multiple candidates'],['@Autowired','Request automatic dependency injection']],'Use @Qualifier for explicit selection or @Primary to establish a default candidate.')
multi('1.12','What benefits can a bounded thread pool provide?',['Thread reuse','Controlled concurrency','Less thread-creation overhead','A guarantee that tasks are never rejected'],[0,1,2],'Bounded pools and queues can reject work under load. Queue size and rejection policies must be chosen deliberately.')
single('1.13','What is the central purpose of database connection pooling?',['Reuse and bound connections to reduce connection setup overhead','Cache every SQL result','Automatically eliminate slow queries','Allow an unlimited number of connections'],'A connection pool manages connections. It is not a query-result cache or a substitute for query optimization.')
pairs('1.14','Match each REST error-handling element to its purpose.',[['@RestControllerAdvice','Provide shared REST controller advice'],['@ExceptionHandler','Handle a designated exception'],['HTTP status code','Communicate response semantics to clients']],'Return a stable error structure and choose a status code that reflects the failure.')
single('1.15','In default proxy-based Spring AOP, what usually happens on a direct internal call to a @Transactional method?',['The call bypasses the proxy, so transactional interception does not apply.','A new transaction is always created.','The code fails to compile.','Only private methods are intercepted.'],'Self-invocation is a common proxy limitation. Transaction advice is normally applied when calls go through the proxy.')
multi('1.16','Which statements about request validation are correct?',['DTO fields can use @NotNull and @Size','@Valid can trigger validation of a request object','Validation failures should become suitable client error responses','@Valid automatically generates business-correct missing values'],[0,1,2],'Validation detects constraint violations. It does not invent missing business data.')
pairs('1.19','Match the three parts of a typical signed JWT.',[['Header','Algorithm and related metadata'],['Payload','Claims such as exp'],['Signature','Integrity and signature verification']],'Header and payload are Base64URL encoded, not automatically encrypted. Decoding is not signature verification.')
multi('1.20','Which token-handling practices are appropriate?',['Use short-lived access tokens','Design a refresh-token revocation mechanism','Validate expiration and required claims','Trust a token whenever Base64 decoding succeeds'],[0,1,2],'Validate signatures, time constraints, and relevant issuer/audience requirements. Decoding alone provides no trust.')
pairs('1.21','Match the transformation to its defining property.',[['Encoding','Reversible representation conversion'],['Encryption','Confidentiality using cryptographic keys'],['Hashing','One-way digest computation']],'Base64 is encoding. Password storage requires an appropriate salted password-hashing algorithm, not just an arbitrary fast hash.')
single('1.22','Which exception normally triggers rollback with default Spring @Transactional settings?',['RuntimeException','Every checked exception, without configuration','Only IOException','No exception triggers rollback'],'By default, RuntimeException and Error trigger rollback. Configure rollbackFor when checked exceptions should also roll back.')
multi('1.23','Which statements fit REST constraints?',['Each request contains the context needed to process it','Resources are accessed through a uniform interface','Client and server responsibilities are separated','The server must store conversational session state for every client'],[0,1,2],'Statelessness concerns client session context. It does not mean an application cannot store database state.')
multi('1.24','Which capabilities are composed by @SpringBootApplication?',['Auto-configuration','Component scanning','Configuration-class declaration','Automatic transaction advice on every method'],[0,1,2],'Its core composition includes @SpringBootConfiguration, @EnableAutoConfiguration, and @ComponentScan.')
single('1.27','Requests are piling up and the service risks OOM. Which response is most appropriate?',['Use bounded queues, rate limits, and backpressure while investigating capacity','Make all queues unbounded','Retry every request without a limit','Only increase logging to TRACE'],'Bounding accumulated work controls memory pressure. Pagination, chunking, and streaming can also reduce peak allocation.')
pairs('1.31','Match the configuration mechanism to its role.',[['@ConfigurationProperties','Bind related properties into a typed object'],['@Value','Inject an individual value or expression'],['@Profile','Activate components for selected environments']],'ConfigurationProperties is well suited to grouped configuration and can be combined with validation.')
pairs('1.32','Match each JUnit 5 annotation.',[['@Test','Declare a test method'],['@BeforeEach','Run before each test'],['@AfterEach','Run after each test'],['@BeforeAll','Run once before tests in the class']],'Lifecycle callbacks set up and clean up test fixtures.')
single('1.33','How can you stub a spy without invoking the real method during stubbing?',['doReturn(value).when(spy).method()','when(spy.method()).thenReturn(value) never calls the real method','Call spy.method() directly','@Mock automatically disables all methods on every spy'],'The argument to when is evaluated first. doReturn-style stubbing avoids invoking the real spy method at setup time.')
single('1.38','Loading N entities and accessing an association triggers N additional queries. What is this called?',['The N+1 query problem','Circular dependency','Thread deadlock','Generic type erasure'],'Consider fetch joins, EntityGraph, batching, or DTO projections based on the access pattern. Making every relation EAGER is not a universal fix.')
order('1.40','Order these stages in a typical Spring MVC controller request.',['DispatcherServlet receives the request','HandlerMapping locates a handler','HandlerAdapter invokes the controller','Convert the return value and write the response'],'Interceptors and exception resolvers may also participate. REST responses commonly use HTTP message converters.')
single('1.41','Which approach is suitable for storing user passwords?',['A salted password-hashing algorithm such as BCrypt','Base64 encoding','Plain text for easy password recovery','Unsalted SHA-256 as the entire password-storage scheme'],'Use a password-specific hashing algorithm with a suitable work factor. Password recovery should normally reset the password.')
pairs('1.46','Match each communication mechanism.',[['Polling','The client periodically asks for updates'],['SSE','The server streams events to the client over HTTP'],['WebSocket','A bidirectional messaging channel']],'Choose based on directionality and operational requirements. Not every real-time interface needs WebSocket.')
single('2.1','Why must equal HashMap keys have equal hashCode values?',['So equal keys can be located consistently in the hash structure','To ensure every distinct object has a unique hash','To make HashMap thread-safe','To preserve insertion order'],'Hashing narrows lookup; equality distinguishes keys. Unequal keys are allowed to have hash collisions.')
multi('2.2','Which approaches can implement a thread-safe singleton?',['An enum singleton','The initialization-on-demand holder idiom','Correct double-checked locking with volatile','Unsynchronized ordinary lazy initialization'],[0,1,2],'Holder initialization uses class-initialization guarantees. Double-checked locking requires correct synchronization and publication.')
pairs('2.3','Match each throwable category to an example.',[['Checked exception','IOException'],['Unchecked exception','NullPointerException'],['Error','OutOfMemoryError']],'Checked exceptions must be caught or declared. RuntimeException subclasses are unchecked.')
single('2.4','What is the essential constraint of a functional interface?',['One abstract method; default and static methods are permitted','One method total, with no default methods','It must extend Thread','It must declare two abstract methods'],'A functional interface supplies a target type for a lambda. Public Object methods do not count toward this abstract-method constraint.')
pairs('2.5','Match each comparison interface to its method.',[['Comparable<T>','compareTo(T other)'],['Comparator<T>','compare(T a, T b)']],'Comparable defines a natural ordering; Comparator provides an external ordering strategy.')
pairs('2.6','Match the OOP principle to its meaning.',[['Encapsulation','Hide internal state and control access'],['Inheritance','Establish a subtype relationship'],['Polymorphism','Invoke different implementations through a common abstraction'],['Abstraction','Expose essential behavior while hiding implementation detail']],'These principles address different design concerns. Inheritance is not the only way to reuse behavior.')
multi('2.7','Which concurrency statements are correct?',['synchronized provides mutual exclusion and visibility guarantees','volatile does not make count++ atomic','A consistent lock-acquisition order can reduce deadlock risk','More threads always increase throughput linearly'],[0,1,2],'Increment is a read-modify-write operation. Throughput is constrained by CPU, I/O, contention, and other resources.')
single('2.9','Which statement about ConcurrentHashMap is correct?',['It disallows both null keys and null values.','It allows null keys but not null values.','Every operation uses one global map lock.','Every traversal throws ConcurrentModificationException.'],'ConcurrentHashMap supports concurrent access. Historical segmented implementations should not be assumed for all Java versions.')
pairs('2.10','Match each CompletableFuture composition method.',[['thenApply','Transform a stage result into a value'],['thenCompose','Flatten a function that returns another stage'],['thenCombine','Combine results from two stages']],'thenCompose is useful for dependent asynchronous work; thenCombine combines two results.')
single('2.11','What does Optional.ofNullable(null) return?',['Optional.empty()','A NullPointerException','An Optional containing the string null','A nonempty Optional containing null'],'Optional.of(null) throws, whereas ofNullable maps a null input to an empty Optional.')
pairs('2.12','Match each collection abstraction.',[['List','An ordered sequence that can contain duplicates'],['Set','Elements without duplicates'],['Map','Key-to-value associations'],['Queue','Elements held for processing']],'A Queue is not necessarily FIFO; PriorityQueue orders elements by priority.')
single('2.13','Which interface must a try-with-resources resource implement?',['AutoCloseable','Runnable','Comparable','Serializable'],'AutoCloseable supplies close(). Multiple resources are normally closed in reverse declaration order.')
multi('2.15','Which practices support immutability?',['Prevent subclasses from violating invariants','Do not expose mutable internal objects','Defensively copy mutable inputs','A final reference alone guarantees deep immutability'],[0,1,2],'final prevents reassignment of the reference; it does not freeze the referenced object.')
pairs('2.19','Match these SOLID principles.',[['Single Responsibility','One primary reason for a class to change'],['Open/Closed','Open for extension, closed for modification'],['Liskov Substitution','Subtypes must remain substitutable'],['Dependency Inversion','High- and low-level modules depend on abstractions']],'Interface Segregation additionally avoids forcing clients to depend on methods they do not need.')
single('2.20','How should you normally compare the contents of two non-null Strings?',['equals()','==','Equality of System.identityHashCode() values','Compare their variable names'],'== compares references; String.equals compares character content.')
pairs('2.22','Match each JVM memory concept.',[['Heap','Memory typically containing GC-managed objects'],['Stack','Thread-local method call frames'],['StackOverflowError','Often caused by excessive call depth']],'Stack frames include local variables and an operand stack. Runtime optimizations can affect concrete layouts.')
order('2.23','Filter adults, sort Person objects by age, and collect their names. Order the pipeline.',['Create a stream of Person objects','filter: retain age >= 18','sorted: compare Person::getAge','map: extract each name','collect: produce the result list'],'After mapping to String, Person::getAge is no longer a valid comparator. This corrects the type-order issue in the 2025 STREAM supplement.')
pairs('3.2','Match each ACID property.',[['Atomicity','All transaction operations succeed or roll back together'],['Consistency','Transactions preserve valid states and constraints'],['Isolation','Control interference between concurrent transactions'],['Durability','Committed results persist']],'ACID consistency is not the same concept as consistency in CAP.')
multi('3.3','Which actions are appropriate when investigating slow SQL?',['Inspect execution plans and measured latency','Evaluate indexes and result-set size','Check lock waits and connection-pool pressure','Index every column without measuring anything'],[0,1,2],'Indexes have write and storage costs. Let measurements guide optimization.')
single('3.5','How is a relational many-to-many relationship usually represented?',['A junction table containing foreign keys to both sides','A comma-separated string containing every related key','It must be moved to a NoSQL database','Each side must contain exactly one row'],'Use appropriate uniqueness constraints. A relationship with business attributes is often modeled as an explicit association entity.')
single('3.6','What is the central CAP trade-off during a network partition?',['Strong consistency and availability cannot both be guaranteed.','Every system always chooses any two letters regardless of conditions.','SQL databases cannot experience partitions.','Adding a cache eliminates all trade-offs.'],'The trade-off concerns behavior during a partition; it is not an unrestricted choose-any-two rule.')
pairs('3.7','Match each locking strategy.',[['Optimistic locking','Compare a version and fail or retry on conflict'],['Pessimistic locking','Acquire a lock before protected operations']],'Optimistic locking commonly uses a version column; pessimistic locking may use SELECT FOR UPDATE.')
order('3.10','Order a typical cache-aside read on a cache miss.',['Look up the cache','Determine that the entry is missing','Read the database','Populate the cache with the result','Return the result to the caller'],'This is the simplified miss path. Real systems also need invalidation, stampede prevention, and null-result policies.')
single('4.3','How can a business transaction span independent service databases?',['Use a Saga with local transactions and compensating actions','A normal local @Transactional automatically covers every service','HTTP provides atomic distributed commit by default','Compensation always performs a physical database rollback'],'A Saga restores business consistency through compensation. Real-world side effects may not be perfectly reversible.')
pairs('4.4','Match each fault-tolerance mechanism.',[['Timeout','Bound the wait for a downstream operation'],['Circuit breaker','Fail fast when downstream failures persist'],['Bulkhead','Isolate resource pools to limit failure spread'],['Retry','Attempt an operation again under suitable conditions']],'Bound retries and combine them with backoff and idempotency to avoid amplifying failures.')
single('4.7','A consumer group has five consumers and subscribes only to a topic with three partitions. What happens?',['At most three consumers receive partitions; the others are idle.','All five consumers simultaneously own every partition.','Kafka automatically increases the partition count to five.','Every consumer stops working.'],'Within one group, a partition is assigned to one consumer at a time.')
single('4.8','What does a committed Kafka offset normally identify?',['The next position for the group to read in a partition','The global number of messages across all topics','A business entity primary key','The IP address of a broker'],'Offsets are partition-specific. The timing of processing versus committing affects replay and loss risks.')
multi('4.9','Which strategies help limit the business impact of duplicate messages?',['Business idempotency keys','Unique constraints or a deduplication table','Producer idempotence where appropriate','Assume acks=all guarantees exactly one write to an external database'],[0,1,2],'Producer idempotence does not guarantee exactly-once external database effects. Consumers still need appropriate safeguards.')
single('4.11','At what scope does Kafka primarily guarantee message order?',['Within a single partition','Globally across every topic','Globally across all consumer groups','Across every partition in the cluster'],'Related keys are commonly routed to one partition. Partition-count changes and partitioner behavior must be considered.')
pairs('4.18','Match each Kafka producer acknowledgment setting.',[['acks=0','Do not wait for broker acknowledgment'],['acks=1','Wait for the leader acknowledgment'],['acks=all','Require the current in-sync replicas to acknowledge']],'Durability and availability also depend on replication factor and min.insync.replicas.')
pairs('4.23','Match each eviction strategy.',[['LRU','Evict the least recently used entry'],['LFU','Evict entries used least frequently'],['FIFO','Evict the earliest inserted entry first']],'TTL expiration and memory-pressure eviction are related but distinct mechanisms.')
order('4.25','Order a typical transactional outbox flow.',['Write business data and an outbox record in one local transaction','Commit the local transaction','A relay reads or captures committed outbox records','Publish the event to the messaging system','The consumer handles the event idempotently'],'The outbox avoids an unsafe database/message dual write. Publication may still repeat, so consumption should be idempotent.')
order('5.2','Order this project\'s PR delivery workflow.',['Create a feature branch and commit changes','Open a pull request','Pass CI checks and complete code review','Merge into the main branch','Run the deployment pipeline'],'CI and review can run concurrently, so they are grouped into one stage here.')
pairs('5.5','Match each scaling direction.',[['Scale out','Increase the number of instances'],['Scale in','Decrease the number of instances'],['Scale up','Increase resources per instance'],['Scale down','Decrease resources per instance']],'Horizontal scaling changes instance count; vertical scaling changes per-instance capacity.')
pairs('5.6','Match each AWS service to its role.',[['ALB','Application-layer HTTP routing'],['NLB','Transport-layer load balancing'],['S3','Object storage'],['EC2','Virtual machine compute']],'These services serve different infrastructure needs. Choose based on the workload.')
pairs('5.12','Match each deployment strategy.',[['Rolling','Replace instances gradually'],['Blue-green','Maintain two environments and switch traffic'],['Canary','Send a small share of traffic to the new version first']],'All strategies need health checks and rollback plans. Blue-green commonly requires extra environment capacity.')
single('5.13','How are a Docker image and a container related?',['An image is a template; a container is a running instance.','An image is the live operating-system process.','Each container must include a separate OS kernel.','Starting a container automatically rewrites the source image.'],'Images contain layered filesystem content. Containers add runtime state and a writable layer.')
pairs('5.18','Match each Kubernetes probe.',[['Liveness','Determine whether a container should be restarted'],['Readiness','Determine whether the workload should receive traffic'],['Startup','Check a potentially slow-starting application']],'Readiness failures normally remove the workload from service endpoints; they do not by themselves restart the container.')
order('5.22','Order a basic first-use Terraform workflow.',['Write infrastructure configuration','Run terraform init','Run terraform plan','Review the proposed changes','Run terraform apply'],'Apply reviewed changes and protect state and sensitive information.')
order('6.1','Order a typical Java memory-leak investigation.',['Confirm persistent growth and suspicious GC behavior in metrics','Capture a heap dump at an appropriate time','Inspect retained objects and paths to GC roots','Fix references that retain objects unnecessarily','Retest and verify that memory stabilizes'],'Rising heap usage alone does not prove a leak. Consider post-GC live data, workload, and retained references.')
pairs('6.2','Match the ELK components.',[['Elasticsearch','Index and search logs'],['Logstash','Ingest and transform logs'],['Kibana','Explore and visualize logs']],'Structured logging and correlation identifiers make centralized logs more useful for investigations.')
pairs('6.3','Match each observability component.',[['Prometheus','Collect and query time-series metrics'],['Grafana','Build visual dashboards'],['Alertmanager','Group and route alert notifications']],'These components can form a metrics, visualization, and notification pipeline.')
multi('6.5','Which signals should be considered together when assessing service health?',['Request latency and error rate','Throughput','CPU, heap use, and garbage collection','Only whether the process exists'],[0,1,2],'A live process can still fail requests. Assess user-facing behavior, traffic, and resource signals together.')
library=json.loads(Path('public/data/library.json').read_text())
aliases=library['aliases']
source_map={x['id']:x for x in library['sources']}
for q in qs:
    q['sourceIds']=[aliases.get(x,x) for x in q['sourceIds']]
    q['category']=source_map[q['sourceIds'][0]]['category']
from more_concepts import extend
extend(qs,library)
covered={id for q in qs for id in q['sourceIds']}
missing=[s['id'] for s in library['sources'] if not s['supplement'] and s['id'] not in covered]
assert not missing,missing
report=json.loads(Path('public/data/coverage.json').read_text())
report.update(conceptExercises=len(qs),conceptCoveredTopics=len(covered),conceptUncoveredTopics=missing)
Path('public/data/coverage.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
Path('public/data/questions.json').write_text(json.dumps(qs,ensure_ascii=False,indent=2));print('Concept questions:',len(qs))
